changeSet.sql:
ALTER TABLE authorities
  ADD COLUMN type VARCHAR(20) NOT NULL DEFAULT 'SCHOLAR';

ALTER TABLE authorities
  ADD CONSTRAINT authorities_type_check
    CHECK (type IN ('SCHOLAR','MUHAQQIQ','PUBLISHER','AUTHOR','OTHER'));

CREATE INDEX idx_authorities_type ON authorities(type);

rollback.sql:
DROP INDEX IF EXISTS idx_authorities_type;
ALTER TABLE authorities DROP CONSTRAINT authorities_type_check;
ALTER TABLE authorities DROP COLUMN type;
